package main

import (
	"context"
	"crypto/sha256"
	"database/sql"
	"errors"
	"fmt"
	"os"
	"sync"

	"github.com/jmoiron/sqlx"
)

// ---------------------------------------------------------------------------
// In-process caches for immutable / rarely-changing rows.
// The benchmark calls /api/initialize between runs, which resets the database.
// Every cache is cleared from initializeHandler both before and after the reset.
// ---------------------------------------------------------------------------

type userCacheEntry struct {
	Model      UserModel
	Theme      ThemeModel
	IconHash   string
	IconData   []byte
	IconLoaded bool
}

type livestreamCacheEntry struct {
	Model  LivestreamModel
	Tags   []Tag
	TagIDs []int64
}

var (
	cacheMu       sync.RWMutex
	userByID      = make(map[int64]*userCacheEntry)
	userByName    = make(map[string]int64)
	livestreamByID = make(map[int64]*livestreamCacheEntry)

	tagsMu     sync.Mutex
	tagsLoaded bool
	allTags    []*TagModel
	tagByID    = make(map[int64]TagModel)
	tagByName  = make(map[string]int64)

	ngMu    sync.RWMutex
	ngCache = make(map[int64][]*NGWord)

	fallbackOnce sync.Once
	fallbackData []byte
	fallbackHash string
)

func clearCaches() {
	cacheMu.Lock()
	userByID = make(map[int64]*userCacheEntry)
	userByName = make(map[string]int64)
	livestreamByID = make(map[int64]*livestreamCacheEntry)
	cacheMu.Unlock()

	tagsMu.Lock()
	tagsLoaded = false
	allTags = nil
	tagByID = make(map[int64]TagModel)
	tagByName = make(map[string]int64)
	tagsMu.Unlock()

	ngMu.Lock()
	ngCache = make(map[int64][]*NGWord)
	ngMu.Unlock()
}

func getFallbackImage() ([]byte, string) {
	fallbackOnce.Do(func() {
		data, err := os.ReadFile(fallbackImage)
		if err == nil {
			fallbackData = data
			fallbackHash = fmt.Sprintf("%x", sha256.Sum256(data))
		} else {
			fallbackHash = fmt.Sprintf("%x", sha256.Sum256(nil))
		}
	})
	return fallbackData, fallbackHash
}

func ensureTags(ctx context.Context) error {
	tagsMu.Lock()
	defer tagsMu.Unlock()
	if tagsLoaded {
		return nil
	}
	var models []*TagModel
	if err := dbConn.SelectContext(ctx, &models, "SELECT * FROM tags ORDER BY id"); err != nil {
		return err
	}
	allTags = models
	tagByID = make(map[int64]TagModel, len(models))
	tagByName = make(map[string]int64, len(models))
	for _, t := range models {
		tagByID[t.ID] = *t
		tagByName[t.Name] = t.ID
	}
	tagsLoaded = true
	return nil
}

func tagsResponse() []*Tag {
	tagsMu.Lock()
	defer tagsMu.Unlock()
	out := make([]*Tag, len(allTags))
	for i, t := range allTags {
		out[i] = &Tag{ID: t.ID, Name: t.Name}
	}
	return out
}

func getTagIDByName(ctx context.Context, name string) (int64, error) {
	if err := ensureTags(ctx); err != nil {
		return 0, err
	}
	tagsMu.Lock()
	id, ok := tagByName[name]
	tagsMu.Unlock()
	if !ok {
		return 0, sql.ErrNoRows
	}
	return id, nil
}

func tagModelsByIDs(ctx context.Context, ids []int64) (map[int64]TagModel, error) {
	if err := ensureTags(ctx); err != nil {
		return nil, err
	}
	out := make(map[int64]TagModel, len(ids))
	tagsMu.Lock()
	for _, id := range ids {
		if t, ok := tagByID[id]; ok {
			out[id] = t
		}
	}
	tagsMu.Unlock()
	return out, nil
}

func putUserEntry(e *userCacheEntry) {
	cacheMu.Lock()
	userByID[e.Model.ID] = e
	userByName[e.Model.Name] = e.Model.ID
	cacheMu.Unlock()
}

func getUserEntryByID(ctx context.Context, id int64) (*userCacheEntry, error) {
	cacheMu.RLock()
	e := userByID[id]
	cacheMu.RUnlock()
	if e != nil {
		return e, nil
	}
	if err := loadUsersByIDs(ctx, []int64{id}); err != nil {
		return nil, err
	}
	cacheMu.RLock()
	e = userByID[id]
	cacheMu.RUnlock()
	if e == nil {
		return nil, sql.ErrNoRows
	}
	return e, nil
}

func getUserEntryByName(ctx context.Context, name string) (*userCacheEntry, error) {
	cacheMu.RLock()
	id, ok := userByName[name]
	var e *userCacheEntry
	if ok {
		e = userByID[id]
	}
	cacheMu.RUnlock()
	if e != nil {
		return e, nil
	}

	var foundID int64
	if err := dbConn.GetContext(ctx, &foundID, "SELECT id FROM users WHERE name = ?", name); err != nil {
		return nil, err
	}
	return getUserEntryByID(ctx, foundID)
}

