// connectDNS opens a small connection used only when a new user registers.
// We insert the A record directly instead of spawning pdnsutil, which is one
// of the most expensive operations in the original implementation.
func connectDNS() (*sqlx.DB, error) {
	conf := mysql.NewConfig()
	conf.Net = "tcp"
	conf.Addr = net.JoinHostPort(getenvDefault("ISUCON13_DNS_DB_ADDRESS", "127.0.0.1"), getenvDefault("ISUCON13_DNS_DB_PORT", "3306"))
	conf.User = getenvDefault("ISUCON13_DNS_DB_USER", "isudns")
	conf.Passwd = getenvDefault("ISUCON13_DNS_DB_PASSWORD", "isudns")
	conf.DBName = getenvDefault("ISUCON13_DNS_DB_DATABASE", "isudns")
	conf.ParseTime = true
	db, err := sqlx.Open("mysql", conf.FormatDSN())
	if err != nil {
		return nil, err
	}
	db.SetMaxOpenConns(20)
	db.SetMaxIdleConns(20)
	db.SetConnMaxLifetime(0)
	if err := db.Ping(); err != nil {
		db.Close()
		return nil, err
	}
	return db, nil
}

func getenvDefault(key, def string) string {
	if v, ok := os.LookupEnv(key); ok && v != "" {
		return v
	}
	return def
}

func addDNSRecord(ctx interface{ Done() <-chan struct{} }, name string) error {
	// ctx is only used through the background context in practice; keep the
	// pdnsutil fallback for environments where the direct connection is not
	// available.
	if dnsConn != nil {
		_, err := dnsConn.Exec("INSERT INTO records (domain_id, name, type, content, ttl, prio, disabled, ordername, auth) VALUES (2, ?, 'A', ?, 0, 0, 0, NULL, 1)", name, powerDNSSubdomainAddress)
		if err == nil {
			return nil
		}
		log.Printf("direct DNS insert failed, falling back to pdnsutil: %v", err)
	}
	if out, err := exec.Command("pdnsutil", "add-record", "u.isucon.dev", name, "A", "0", powerDNSSubdomainAddress).CombinedOutput(); err != nil {
		return fmt.Errorf("%s: %w", string(out), err)
	}
	return nil
}

