package main

import (
	"database/sql"
	"errors"
	"net/http"
	"strconv"

	"github.com/labstack/echo/v4"
)

type LivestreamStatistics struct {
	Rank           int64 `json:"rank"`
	ViewersCount   int64 `json:"viewers_count"`
	TotalReactions int64 `json:"total_reactions"`
	TotalReports   int64 `json:"total_reports"`
	MaxTip         int64 `json:"max_tip"`
}

type UserStatistics struct {
	Rank              int64  `json:"rank"`
	ViewersCount      int64  `json:"viewers_count"`
	TotalReactions    int64  `json:"total_reactions"`
	TotalLivecomments int64  `json:"total_livecomments"`
	TotalTip          int64  `json:"total_tip"`
	FavoriteEmoji     string `json:"favorite_emoji"`
}

func getUserStatisticsHandler(c echo.Context) error {
	ctx := c.Request().Context()

	if err := verifyUserSession(c); err != nil {
		return err
	}

	username := c.Param("username")
	user, err := getUserEntryByName(ctx, username)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return echo.NewHTTPError(http.StatusBadRequest, "not found user that has the given username")
		}
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to get user: "+err.Error())
	}
	targetID := user.Model.ID

	// One aggregate query produces all users' scores. The original issued two
	// queries per user (over 2400 queries for the seeded data).
	type rankingRow struct {
		Name  string `db:"name"`
		Score int64  `db:"score"`
	}
	var ranking []rankingRow
	query := `
	SELECT u.name,
	       IFNULL(r.cnt, 0) + IFNULL(lc.tip, 0) AS score
	FROM users u
	LEFT JOIN (
	  SELECT l.user_id, COUNT(*) AS cnt
	  FROM livestreams l INNER JOIN reactions r ON r.livestream_id = l.id
	  GROUP BY l.user_id
	) r ON r.user_id = u.id
	LEFT JOIN (
	  SELECT l.user_id, IFNULL(SUM(lc.tip), 0) AS tip
	  FROM livestreams l INNER JOIN livecomments lc ON lc.livestream_id = l.id
	  GROUP BY l.user_id
	) lc ON lc.user_id = u.id`
	if err := dbConn.SelectContext(ctx, &ranking, query); err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to get ranking: "+err.Error())
	}

	var targetScore int64
	for _, r := range ranking {
		if r.Name == username {
			targetScore = r.Score
			break
		}
	}
	var rank int64 = 1
	for _, r := range ranking {
		if r.Score > targetScore || (r.Score == targetScore && r.Name > username) {
			rank++
		}
	}

	var totalReactions int64
	if err := dbConn.GetContext(ctx, &totalReactions, `SELECT COUNT(*)
		FROM livestreams l INNER JOIN reactions r ON r.livestream_id = l.id
		WHERE l.user_id = ?`, targetID); err != nil && !errors.Is(err, sql.ErrNoRows) {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to count total reactions: "+err.Error())
	}

	var totalLivecomments int64
	var totalTip int64
	if err := dbConn.QueryRowContext(ctx, `SELECT COUNT(*), IFNULL(SUM(lc.tip), 0)
		FROM livestreams l INNER JOIN livecomments lc ON lc.livestream_id = l.id
		WHERE l.user_id = ?`, targetID).Scan(&totalLivecomments, &totalTip); err != nil && !errors.Is(err, sql.ErrNoRows) {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to count livecomments: "+err.Error())
	}

	var viewersCount int64
	if err := dbConn.GetContext(ctx, &viewersCount, `SELECT COUNT(*)
		FROM livestreams l INNER JOIN livestream_viewers_history h ON h.livestream_id = l.id
		WHERE l.user_id = ?`, targetID); err != nil && !errors.Is(err, sql.ErrNoRows) {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to get livestream_view_history: "+err.Error())
	}

	var favoriteEmoji sql.NullString
	if err := dbConn.GetContext(ctx, &favoriteEmoji, `SELECT r.emoji_name
		FROM livestreams l INNER JOIN reactions r ON r.livestream_id = l.id
		WHERE l.user_id = ?
		GROUP BY r.emoji_name
		ORDER BY COUNT(*) DESC, r.emoji_name DESC
		LIMIT 1`, targetID); err != nil && !errors.Is(err, sql.ErrNoRows) {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to find favorite emoji: "+err.Error())
	}

	stats := UserStatistics{
		Rank:              rank,
		ViewersCount:      viewersCount,
		TotalReactions:    totalReactions,
		TotalLivecomments: totalLivecomments,
		TotalTip:          totalTip,
		FavoriteEmoji:     favoriteEmoji.String,
	}
	return c.JSON(http.StatusOK, stats)
}

func getLivestreamStatisticsHandler(c echo.Context) error {
	ctx := c.Request().Context()

	if err := verifyUserSession(c); err != nil {
		return err
	}

	id, err := strconv.Atoi(c.Param("livestream_id"))
	if err != nil {
		return echo.NewHTTPError(http.StatusBadRequest, "livestream_id in path must be integer")
	}
	livestreamID := int64(id)

	if _, err := getLivestreamEntry(ctx, livestreamID); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return echo.NewHTTPError(http.StatusBadRequest, "cannot get stats of not found livestream")
		}
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to get livestream: "+err.Error())
	}

	type rankingRow struct {
		ID    int64 `db:"id"`
		Score int64 `db:"score"`
	}
	var ranking []rankingRow
	query := `
	SELECT l.id, IFNULL(r.cnt, 0) + IFNULL(lc.tip, 0) AS score
	FROM livestreams l
	LEFT JOIN (
	  SELECT livestream_id, COUNT(*) AS cnt FROM reactions GROUP BY livestream_id
	) r ON r.livestream_id = l.id
	LEFT JOIN (
	  SELECT livestream_id, IFNULL(SUM(tip), 0) AS tip FROM livecomments GROUP BY livestream_id
	) lc ON lc.livestream_id = l.id`
	if err := dbConn.SelectContext(ctx, &ranking, query); err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to get ranking: "+err.Error())
	}

	var targetScore int64
	for _, r := range ranking {
		if r.ID == livestreamID {
			targetScore = r.Score
			break
		}
	}
	var rank int64 = 1
	for _, r := range ranking {
		if r.Score > targetScore || (r.Score == targetScore && r.ID > livestreamID) {
			rank++
		}
	}

	var counts struct {
		Viewers   int64 `db:"viewers"`
		MaxTip    int64 `db:"max_tip"`
		Reactions int64 `db:"reactions"`
		Reports   int64 `db:"reports"`
	}
	if err := dbConn.GetContext(ctx, &counts, `SELECT
		(SELECT COUNT(*) FROM livestream_viewers_history WHERE livestream_id = ?) AS viewers,
		(SELECT IFNULL(MAX(tip), 0) FROM livecomments WHERE livestream_id = ?) AS max_tip,
		(SELECT COUNT(*) FROM reactions WHERE livestream_id = ?) AS reactions,
		(SELECT COUNT(*) FROM livecomment_reports WHERE livestream_id = ?) AS reports`,
		livestreamID, livestreamID, livestreamID, livestreamID); err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to collect livestream statistics: "+err.Error())
	}

	return c.JSON(http.StatusOK, LivestreamStatistics{
		Rank:           rank,
		ViewersCount:   counts.Viewers,
		MaxTip:         counts.MaxTip,
		TotalReactions: counts.Reactions,
		TotalReports:   counts.Reports,
	})
}
EOF
